hooks.command:
if command -v python3 >/dev/null 2>&1; then py=python3; elif command -v python >/dev/null 2>&1; then py=python; else py=; fi; fallback='{"systemMessage":"[delegate-channel/warn] Guard unavailable, failed, or timed out; native spawn allowed fail-open.","suppressOutput":false}'; if [ -z "$py" ]; then printf '%s\n' "$fallback"; else out=$("$py" -c 'import json,subprocess,sys
mode=sys.argv[1]
reason="[delegate-channel/warn] Guard unavailable, failed, or timed out; native delegation allowed fail-open."
fallback={"systemMessage":reason,"suppressOutput":False}
if mode=="pre":
    fallback={"systemMessage":reason,"suppressOutput":False}
try:
    completed=subprocess.run(sys.argv[2:],input=sys.stdin.buffer.read(),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=8)
    candidate=json.loads(completed.stdout.decode("utf-8"))
    valid=completed.returncode==0 and isinstance(candidate,dict)
    if mode=="pre":
        hook=candidate.get("hookSpecificOutput",{}) if valid else {}
        deny=(valid and set(candidate)=={"decision","reason","hookSpecificOutput","systemMessage","suppressOutput"} and isinstance(hook,dict) and set(hook)=={"hookEventName","permissionDecision","permissionDecisionReason"} and candidate.get("decision")=="block" and hook.get("hookEventName")=="PreToolUse" and hook.get("permissionDecision")=="deny" and isinstance(candidate.get("reason"),str) and candidate.get("reason")==hook.get("permissionDecisionReason")==candidate.get("systemMessage") and candidate.get("suppressOutput") is False)
        allow=valid and candidate=={}
        warning=(valid and set(candidate)=={"systemMessage","suppressOutput"} and isinstance(candidate.get("systemMessage"),str) and candidate.get("suppressOutput") is False)
        valid=deny or allow or warning
    else:
        valid=valid and isinstance(candidate.get("suppressOutput"),bool)
    if not valid:
        raise ValueError("invalid guard envelope")
except Exception:
    candidate=fallback
sys.stdout.write(json.dumps(candidate,separators=(",",":"))+"\n")' pre "$py" .project_manager/tools/delegate_channel_guard.py codex-hook); rc=$?; if [ "$rc" -eq 0 ] && [ -n "$out" ]; then printf '%s\n' "$out"; else printf '%s\n' "$fallback"; fi; fi

