hooks.command:
if command -v python3 >/dev/null 2>&1; then py=python3; elif command -v python >/dev/null 2>&1; then py=python; else py=; fi; fallback='{"systemMessage":"[delegate-channel/warn] SubagentStart observer unavailable, failed, or timed out; native spawn remains allowed fail-open.","suppressOutput":false}'; if [ -z "$py" ]; then printf '%s\n' "$fallback"; else out=$("$py" -c 'import json,subprocess,sys
mode=sys.argv[1]
reason="[delegate-channel/warn] Guard unavailable, failed, or timed out; native delegation allowed fail-open."
fallback={"systemMessage":reason,"suppressOutput":False}
if mode=="pre":
    fallback={"decision":"approve","reason":reason,"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"allow","permissionDecisionReason":reason},"systemMessage":reason,"suppressOutput":False}
try:
    completed=subprocess.run(sys.argv[2:],input=sys.stdin.buffer.read(),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=8)
    candidate=json.loads(completed.stdout.decode("utf-8"))
    valid=completed.returncode==0 and isinstance(candidate,dict)
    if mode=="pre":
        hook=candidate.get("hookSpecificOutput",{}) if valid else {}
        valid=valid and candidate.get("decision") in {"approve","block"} and hook.get("permissionDecision") in {"allow","deny","ask"}
    else:
        valid=valid and isinstance(candidate.get("suppressOutput"),bool)
    if not valid:
        raise ValueError("invalid guard envelope")
except Exception:
    candidate=fallback
sys.stdout.write(json.dumps(candidate,separators=(",",":"))+"\n")' observe "$py" .project_manager/tools/delegate_channel_guard.py codex-subagent-observe); rc=$?; if [ "$rc" -eq 0 ] && [ -n "$out" ]; then printf '%s\n' "$out"; else printf '%s\n' "$fallback"; fi; fi

